import sys; sys.path.insert(0, '_tools'); from spec import enrich
# Sin alabanza al inicio (el video arranca con el predicador): sin `inicio`.
enrich('conocimiento-verdadero-iii', 'C',
 [dict(t=612, e=660, titulo='Los grandes conocen el camino', txt='«Me dirigiré a los grandes.» ¿A quiénes se va a dirigir entonces? A los grandes. ¿Cómo los miran los otros? Pequeños. «Y les hablaré, porque ellos sí conocen el camino del Señor y las ordenanzas de Dios.» Los grandes, no los pequeños, los que se quedaron chiquitos. Pero también todos ellos a una habían quebrado el yugo y roto las coyundas. Entonces, ¿por qué eran grandes? Porque no se quedaron con los yugos, porque no se quedaron con las coyundas.'),
  dict(t=1202, e=1241, titulo='El Señor sana la herida', txt='Hay herida, hay herida, hay herida. Pero hoy el Señor te la va a sanar. Todo aquel que crea que Dios lo va a sanar, lo va a sanar. Póngase de pie, sin miedo, los que se sienten heridos, porque voy a orar por usted: que tuvo una relación, o sus papás lo hirieron, no lo entendieron. Póngase de pie, porque son más. Y a mí me puso Dios a orar por todos los que están así.'),
  dict(t=1802, e=1856, titulo='Bendito por la sangre de Cristo', txt='Cuando cayó la sangre a la tierra, la bendijo para nosotros. Todo aquel que tiene la sangre de Cristo es bendito. Todas las maldiciones se quedan tiradas. Por eso hay que reclamar ser hijo de Dios. Lo que me llama la atención es que dice: «Espinos y abrojos te producirá, y comerás de las plantas del campo.» Qué difícil, hermano: si hay espinos y abrojos, hay que arrancarlos, con el sudor de tu rostro.')],
 [dict(t=42, txt='«Los tiempos de ignorancia.» A ellos les conviene que usted se quede tonto, que no sepa nada. Pero en el evangelio no se puede.'),
  dict(t=1243, txt='Hasta el día de hoy, ya no más, porque el Señor está vendando tus heridas y te está echando aceite, unción y vino, que es gozo.'),
  dict(t=2427, txt='Si usted le puede dejar un terrenito a su hijo, déjeselo; pero mejor déjele la Palabra de Dios.')],
 ['«Los tiempos de ignorancia.» ¿Hay algo que Dios ya te mostró y que sigues dejando para después?',
  'El predicador invita a ponerse de pie a quienes tienen una herida. ¿Cuál herida le quieres presentar hoy al Señor para que la sane?',
  '«Mejor déjele la Palabra de Dios.» ¿Qué principio de la Palabra puedes sembrar esta semana en tus hijos o en alguien que te sigue?'],
 )
